# Workboard

Requires Node.js 22.22.1. No packages need to be installed.

```sh
npm start
```

The server binds to `0.0.0.0`, using `PORT` (default `8080`). Set `DB_PATH`
to the SQLite file to retain projects, archive state, defaults, tasks, priorities, due dates, and completion state across
restarts; the default is `data/workboard.sqlite`. Its parent directory is created automatically.
`GET /health` returns `{"status":"ok"}`.

```sh
PORT=8080 DB_PATH=./data/workboard.sqlite npm start
npm test
```

Tests use temporary databases outside the repository and remove them afterward.

The project list starts with Active projects; switch Project filter to Archived to
open or restore an archived project. Archived project tasks can be viewed and
filtered, but creation and completion changes are disabled. Completion summaries
count every task in each project. Existing databases are migrated automatically.

On an active project page, use New project name and Rename project to change its
name. Names are trimmed and cannot be blank. Renaming preserves the project's URL,
list position, tasks, and completion summary. Archived projects must be restored
before they can be renamed.

Each task row provides New task title and Rename task. Titles are trimmed and
cannot be blank. Renaming preserves ownership, creation order, completion state,
and completion summaries. Task rename controls are disabled while the project
is archived and become available after restoration.

Each task has a Task priority dropdown with Low, Normal, and High options.
Existing tasks retain their saved priority. Priority is saved independently for
each task and survives renaming, completion changes, and restarts. Archived
projects disable priority edits; restoration preserves the saved priorities.

Project pages start with All selected in both Task filter and Priority filter.
Tasks must match both filters and retain their creation order. Changing either
filter preserves the other selection. Completion and priority edits immediately
update which rows match; renaming preserves both selections. Both filters remain
available on archived projects. Filters do not change saved data or summaries.

Default task priority saves a separate Low, Normal, or High default for each
project. Existing and new projects initially use Normal. New tasks inherit the
project's saved default; changing it never updates existing tasks or either
filter. The default survives renaming and restarts. Archived projects show it
in a disabled dropdown, and restoration enables editing again.

Each task has an optional Task due date textbox and Save due date button. Use a
real Gregorian date in YYYY-MM-DD format (years 0001–9999), or leave it blank to
clear the saved date. Surrounding whitespace is trimmed. Invalid dates show an
alert and preserve the saved date. Dates are calendar days without timezone
conversion and survive other edits and restarts. Archived projects disable date
editing; restoration preserves dates and enables editing again.

Due from and Due through apply an inclusive due-date range alongside the
completion and priority filters. Either blank boundary is unbounded; with both
blank, undated tasks also match. Enter valid YYYY-MM-DD dates and select Apply
due range. Invalid dates or reversed boundaries show an alert and leave the
previous applied range intact. Editing the textboxes alone does not apply a
range. Task edits immediately update matching rows while preserving all filters.
Range controls remain available in archived projects. Reopening a project starts
with empty boundaries; filters never change saved task data or completion summaries.
import { normalizeDueDate } from './task-due-date.js';

export function normalizeDueRange(from, through) {
  let range;
  try {
    range = { from: normalizeDueDate(from), through: normalizeDueDate(through) };
  } catch {
    throw new Error('Due range must use valid YYYY-MM-DD dates');
  }
  if (range.from && range.through && range.from > range.through) {
    throw new Error('Due from must not be after Due through');
  }
  return range;
}

export function matchesTaskFilters(task, completionFilter, priorityFilter, dueRange = { from: '', through: '' }) {
  const matchesCompletion = completionFilter === 'all'
    || (completionFilter === 'completed' ? task.completed : !task.completed);
  const matchesPriority = priorityFilter === 'all' || task.priority === priorityFilter;
  const matchesDueRange = (!dueRange.from && !dueRange.through)
    || Boolean(task.dueDate
      && (!dueRange.from || task.dueDate >= dueRange.from)
      && (!dueRange.through || task.dueDate <= dueRange.through));
  return matchesCompletion && matchesPriority && matchesDueRange;
}
export function normalizeDueDate(value) {
  if (typeof value === 'string') {
    const date = value.trim();
    if (!date) return '';
    const match = date.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (match) {
      const [year, month, day] = match.slice(1).map(Number);
      const leapYear = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
      const daysInMonth = [31, leapYear ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
      if (year >= 1 && month >= 1 && month <= 12 && day >= 1 && day <= daysInMonth[month - 1]) {
        return date;
      }
    }
  }
  const error = new Error('Due date must be a valid YYYY-MM-DD date');
  error.status = 400;
  throw error;
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { matchesTaskFilters, normalizeDueRange } from '../public/task-filters.js';

test('every combination of completion and priority filters matches their intersection', () => {
  for (const completed of [false, true]) {
    for (const priority of ['Low', 'Normal', 'High']) {
      const task = Object.freeze({ title: 'Task', completed, priority });
      for (const completionFilter of ['all', 'open', 'completed']) {
        for (const priorityFilter of ['all', 'Low', 'Normal', 'High']) {
          const expectedCompletion = completionFilter === 'all'
            || completionFilter === (completed ? 'completed' : 'open');
          const expectedPriority = priorityFilter === 'all' || priorityFilter === priority;
          assert.equal(
            matchesTaskFilters(task, completionFilter, priorityFilter),
            expectedCompletion && expectedPriority,
            `${completed}, ${priority}, ${completionFilter}, ${priorityFilter}`,
          );
        }
      }
    }
  }
});

test('filtered rows retain creation order and re-evaluate edited data without altering other tasks', () => {
  const tasks = [
    { id: 1, title: 'First', completed: false, priority: 'High' },
    { id: 2, title: 'Second', completed: true, priority: 'High' },
    { id: 3, title: 'Third', completed: false, priority: 'Low' },
    { id: 4, title: 'Fourth', completed: false, priority: 'High' },
  ];
  const original = structuredClone(tasks);
  const rows = (completion, priority) => tasks
    .filter((task) => matchesTaskFilters(task, completion, priority))
    .map((task) => task.id);
  assert.deepEqual(rows('all', 'all'), [1, 2, 3, 4]);
  assert.deepEqual(rows('open', 'High'), [1, 4]);
  assert.deepEqual(rows('completed', 'Low'), []);
  assert.deepEqual(tasks, original);

  tasks[0].title = 'Renamed';
  assert.deepEqual(rows('open', 'High'), [1, 4]);
  tasks[0].priority = 'Normal';
  assert.deepEqual(rows('open', 'High'), [4]);
  tasks[2].priority = 'High';
  assert.deepEqual(rows('open', 'High'), [3, 4]);
  tasks[2].completed = true;
  assert.deepEqual(rows('open', 'High'), [4]);
  assert.deepEqual(rows('completed', 'High'), [2, 3]);
  tasks[1].completed = false;
  assert.deepEqual(rows('open', 'High'), [2, 4]);
  assert.deepEqual(tasks[3], original[3]);
});

test('due ranges trim and validate both boundaries before checking their order', () => {
  for (const [from, through] of [
    ['', ''], ['0001-01-01', '9999-12-31'], ['2000-02-29', '2000-02-29'],
    ['', '2026-10-10'], ['2026-10-10', ''],
  ]) {
    assert.deepEqual(normalizeDueRange(` \t${from} `, ` ${through}\n`), { from, through });
  }
  for (const invalid of [
    '0000-01-01', '10000-01-01', '1900-02-29', '2026-04-31', '2026-1-01',
    '2026-01-1', '2026/01/01', '2026-10-10T00:00:00Z', 'bad', null,
  ]) {
    assert.throws(() => normalizeDueRange(invalid, ''), {
      message: 'Due range must use valid YYYY-MM-DD dates',
    });
    assert.throws(() => normalizeDueRange('9999-12-31', invalid), {
      message: 'Due range must use valid YYYY-MM-DD dates',
    });
  }
  assert.throws(() => normalizeDueRange('2026-10-11', '2026-10-10'), {
    message: 'Due from must not be after Due through',
  });
});

test('inclusive due ranges intersect every completion and priority filter without changing data', () => {
  const dates = ['', '0001-01-01', '2024-02-28', '2024-02-29', '2024-03-01', '9999-12-31'];
  const ranges = [
    { from: '', through: '' },
    { from: '2024-02-29', through: '' },
    { from: '', through: '2024-02-29' },
    { from: '2024-02-29', through: '2024-02-29' },
    { from: '0001-01-01', through: '9999-12-31' },
  ];
  const expectedDates = [dates, dates.slice(3), dates.slice(1, 4), [dates[3]], dates.slice(1)];
  for (const completed of [false, true]) {
    for (const priority of ['Low', 'Normal', 'High']) {
      for (const dueDate of dates) {
        const task = Object.freeze({ completed, priority, dueDate });
        for (const completionFilter of ['all', 'open', 'completed']) {
          for (const priorityFilter of ['all', 'Low', 'Normal', 'High']) {
            ranges.forEach((range, index) => {
              assert.equal(matchesTaskFilters(task, completionFilter, priorityFilter, Object.freeze(range)),
                (completionFilter === 'all' || completionFilter === (completed ? 'completed' : 'open'))
                && (priorityFilter === 'all' || priorityFilter === priority)
                && expectedDates[index].includes(dueDate),
                `${completed}, ${priority}, ${dueDate}, ${completionFilter}, ${priorityFilter}, ${index}`);
            });
          }
        }
      }
    }
  }
});

test('applied ranges survive invalid drafts and task edits re-evaluate membership in creation order', () => {
  const tasks = [
    { id: 1, title: 'First', completed: false, priority: 'High', dueDate: '2026-10-10' },
    { id: 2, title: 'Second', completed: false, priority: 'High', dueDate: '' },
    { id: 3, title: 'Third', completed: true, priority: 'High', dueDate: '2026-10-10' },
    { id: 4, title: 'Fourth', completed: false, priority: 'Low', dueDate: '2026-10-10' },
    { id: 5, title: 'Fifth', completed: false, priority: 'High', dueDate: '2026-10-11' },
  ];
  let range = normalizeDueRange('2026-10-10', '2026-10-10');
  const rows = (completion = 'open', priority = 'High') => tasks
    .filter((task) => matchesTaskFilters(task, completion, priority, range))
    .map((task) => task.id);
  assert.deepEqual(rows(), [1]);
  for (const draft of [['bad', ''], ['2026-10-11', '2026-10-10']]) {
    assert.throws(() => { range = normalizeDueRange(...draft); });
    assert.deepEqual(rows(), [1]);
  }
  tasks[0].title = 'Renamed';
  assert.deepEqual(rows(), [1]);
  tasks[1].dueDate = '2026-10-10';
  assert.deepEqual(rows(), [1, 2]);
  tasks[0].dueDate = '';
  assert.deepEqual(rows(), [2]);
  tasks[2].completed = false;
  assert.deepEqual(rows(), [2, 3]);
  tasks[3].priority = 'High';
  assert.deepEqual(rows(), [2, 3, 4]);
  tasks[4].dueDate = '2026-10-10';
  assert.deepEqual(rows(), [2, 3, 4, 5]);
  assert.deepEqual(rows('all', 'all'), [2, 3, 4, 5]);
  tasks[4].dueDate = '2026-10-09';
  assert.deepEqual(rows(), [2, 3, 4]);
  tasks.push({ id: 6, title: 'New task', completed: false, priority: 'High', dueDate: '' });
  assert.deepEqual(rows(), [2, 3, 4]);
  range = normalizeDueRange('', '');
  assert.deepEqual(rows(), [1, 2, 3, 4, 5, 6]);
});
